"""The shared cases (sdk/cases, generated by the Rust SDK's tests; sdk/README.md, "The shared
cases").

For every case and run, this test starts itself as a child process (fresh SDK state), the child
makes the case's calls through hydo_assert and hydo_assert.history, and the parent compares what
the sink received and what the calls returned with the case's files. Python has no float32, so
cases that need "f32" are skipped (and reported).

    python3 -m unittest discover -s sdk/python/tests
"""

import asyncio
import glob
import itertools
import json
import os
import re
import subprocess
import sys
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
CASES = os.path.normpath(os.path.join(HERE, "..", "..", "cases"))
PRE = b"PRE existing line\n"
UNSUPPORTED = {"f32": "Python has no float32"}
KNOWN = {"f32", "bytes", "invalid_utf8", "raw_hist"}


def mask_times(b):
    """The time field of each HYDO-HIST record becomes "*"; the times must be decimal integers
    that never decrease."""
    out, prev = [], -1
    for line in b.splitlines(keepends=True):
        if line.startswith(b"HYDO-HIST "):
            f = line.split(b" ", 5)
            if len(f) < 6 or not re.fullmatch(rb"[0-9]+", f[4]) or int(f[4]) < prev:
                raise AssertionError("bad time field in %r" % line)
            prev = int(f[4])
            f[4] = b"*"
            line = b" ".join(f)
        out.append(line)
    return b"".join(out)


def first_difference(want, got):
    w, g = want.split(b"\n"), got.split(b"\n")
    for i in range(max(len(w), len(g))):
        a = w[i] if i < len(w) else None
        b = g[i] if i < len(g) else None
        if a != b:
            return "line %d:\n    case:   %r\n    python: %r" % (i + 1, a, b)
    return "(equal)"


def read(path):
    with open(path, "rb") as f:
        return f.read()


def run_case(path, run):
    """Runs one run of a case in a child process; returns (output bytes, returns)."""
    with tempfile.TemporaryDirectory() as tmp:
        env = {k: v for k, v in os.environ.items() if not k.startswith("HYDO_")}
        env["HYDO_CASE_FILE"] = path
        env["HYDO_CASE_RETURNS"] = os.path.join(tmp, "returns")
        if run["buggify_env"] is not None:
            env["HYDO_BUGGIFY"] = run["buggify_env"]
        if run["buggify_file"] is not None:
            with open(os.path.join(tmp, "buggify"), "w", encoding="utf-8", newline="") as f:
                f.write(run["buggify_file"])
            env["HYDO_BUGGIFY_FILE"] = os.path.join(tmp, "buggify")
        else:
            env["HYDO_BUGGIFY_FILE"] = os.path.join(tmp, "no-buggify")
        console, hist = os.path.join(tmp, "console"), os.path.join(tmp, "hist")
        out, hout = run["out"], run["hist_out"]
        if out in ("file", "append"):
            with open(console, "wb") as f:
                f.write(PRE if out == "append" else b"")
            env["HYDO_ASSERT_OUT"] = console
        elif out in ("stderr", "off"):
            env["HYDO_ASSERT_OUT"] = out
        elif out == "missing":
            env["HYDO_ASSERT_OUT"] = os.path.join(tmp, "missing")
        else:
            raise AssertionError("out %r" % out)
        if hout in ("file", "append"):
            with open(hist, "wb") as f:
                f.write(PRE if hout == "append" else b"")
            env["HYDO_HIST_OUT"] = hist
        elif hout == "create":
            env["HYDO_HIST_OUT"] = hist
        elif hout in ("stderr", "off"):
            env["HYDO_HIST_OUT"] = hout
        elif hout == "fallback":
            env["HYDO_HIST_OUT"] = os.path.join(tmp, "no-such-dir", "hist")
        else:
            raise AssertionError("hist_out %r" % hout)
        p = subprocess.run([sys.executable, os.path.abspath(__file__), "--child"], env=env, capture_output=True)
        if p.returncode != 0:
            raise AssertionError("child failed (%d):\n%s%s" % (p.returncode, p.stdout.decode(errors="replace"), p.stderr.decode(errors="replace")))
        to_stderr = out in ("stderr", "missing") or hout in ("stderr", "fallback")
        if not to_stderr and p.stderr:
            raise AssertionError("wrote to stderr: %r" % p.stderr)
        if to_stderr:
            got = p.stderr
        elif out != "off":
            got = read(console)
        elif hout != "off":
            got = read(hist)
        else:
            got = b""
        with open(os.path.join(tmp, "returns"), encoding="ascii") as f:
            returns = f.read()
        return mask_times(got), returns


class SharedCases(unittest.TestCase):
    def test_cases(self):
        files = sorted(glob.glob(os.path.join(CASES, "*", "*.json")))
        self.assertTrue(files, "no cases in " + CASES)
        ran, skipped = 0, {}
        for path in files:
            with open(path, encoding="utf-8") as f:
                case = json.load(f)
            cid = os.path.relpath(path, CASES)[: -len(".json")]
            unknown = set(case["needs"]) - KNOWN
            self.assertFalse(unknown, "%s needs %s: update this test" % (cid, sorted(unknown)))
            why = [UNSUPPORTED[n] for n in case["needs"] if n in UNSUPPORTED]
            if why:
                skipped[why[0]] = skipped.get(why[0], 0) + 1
                continue
            for run in case["runs"]:
                with self.subTest(case=cid, run=run["name"]):
                    got, returns = run_case(path, run)
                    want = read(os.path.join(os.path.dirname(path), run["output"]))
                    self.assertTrue(got == want, "output differs from %s, %s" % (run["output"], first_difference(want, got)))
                    self.assertEqual(returns, run["returns"], "returns differ")
                    ran += 1
        for why, n in sorted(skipped.items()):
            sys.stderr.write("shared cases: skipped %d cases: %s\n" % (n, why))
        sys.stderr.write("shared cases: %d runs of %d case files\n" % (ran, len(files)))


# ---- the child ----


def s(x):
    """A case string: text, or {"raw": [...]} whose bytes become surrogateescape characters
    (Python's form of undecodable bytes)."""
    if isinstance(x, str):
        return x
    return "".join(p if isinstance(p, str) else chr(0xDC00 + p) for p in x["raw"])


def number(t):
    return float({"+Inf": "inf", "-Inf": "-inf"}.get(t, t))


def val(x):
    if x is None or isinstance(x, (bool, str)):
        return x
    if isinstance(x, list):
        return [val(e) for e in x]
    (tag, y), = x.items()
    if tag in ("int", "uint"):
        return int(y)
    if tag == "f64":
        return number(y)
    if tag == "raw":
        return s(x)
    if tag == "bytes":
        return bytes.fromhex(y)
    if tag == "map":
        return {s(k): val(v) for k, v in y}
    raise AssertionError("value tag %r" % tag)


def details(step):
    return val(step["details"]) if "details" in step else None


def arg(x, h):
    if isinstance(x, str) or "raw" in x:
        return s(x)
    (tag, y), = x.items()
    if tag == "enc":
        return h.enc(s(y))
    if tag == "ver":
        return h.ver(s(y[0]), int(y[1]))
    if tag == "value_or_nil":
        return h.value_or_nil(None if y is None else s(y))
    if tag == "list":
        return h.list_value(*[s(e) for e in y])
    if tag == "append_mop":
        return h.append_mop(s(y[0]), s(y[1]))
    if tag == "read_mop":
        return h.read_mop(s(y))
    if tag == "read_result_mop":
        return h.read_result_mop(s(y[0]), *[s(e) for e in y[1]])
    if tag == "nil":
        return h.NIL
    raise AssertionError("argument tag %r" % tag)


def child():
    sys.path.insert(0, os.path.join(HERE, "..", "src"))
    import hydo_assert as ha
    from hydo_assert import _eventually
    from hydo_assert import history as h

    # The cases hold elapsed_ms 0 for every episode (each ends at once, and one with a deadline
    # of 0 ms is late because some time passed); under the guest's deterministic clock that is
    # what happens. The host's clock is not deterministic: on a busy machine a millisecond can
    # pass between begin and done. So the child's monotonic clock advances by one nanosecond
    # per reading (test_hydo_assert.py tests eventually against the real clock).
    _eventually._now_ns = itertools.count(1).__next__

    with open(os.environ["HYDO_CASE_FILE"], encoding="utf-8") as f:
        case = json.load(f)
    objs, watches, hists, ops, ret = [], [], [], [], []
    push = lambda b: ret.append("1" if b else "0")  # noqa: E731
    args = lambda st: [arg(a, h) for a in st["args"]]  # noqa: E731
    decl = {
        "always": ha.always,
        "always_or_unreachable": ha.always_or_unreachable,
        "sometimes": ha.sometimes,
        "reachable": ha.reachable,
        "unreachable": ha.unreachable,
    }
    for st in case["steps"]:
        do = st["do"]
        if do in decl:
            objs.append(decl[do](s(st["id"]), s(st["msg"])))
        elif do == "eventually":
            objs.append(ha.eventually(s(st["id"]), s(st["msg"]), st["within_ms"] / 1000))
        elif do == "buggify":
            objs.append(ha.buggify(s(st["id"]), s(st["msg"])))
        elif do == "check":
            push(objs[st["a"]].check(st["cond"], details(st)))
        elif do == "hit":
            objs[st["a"]].hit(details(st))
        elif do == "cmp":
            a, left, right = objs[st["a"]], val(st["left"]), val(st["right"])
            push(a.cmp(left, st["op"], right, details(st)))
        elif do == "begin":
            watches.append(objs[st["a"]].begin())
        elif do == "done":
            push(watches[st["w"]].done(details(st)))
        elif do == "expire":
            watches[st["w"]].expire(details(st))
        elif do == "await":
            if st.get("async"):
                push(asyncio.run(objs[st["a"]].await_async(lambda: True, 0.001, details(st))))
            else:
                push(objs[st["a"]].await_cond(lambda: True, 0.001, details(st)))
        elif do == "fire":
            push(objs[st["a"]].fire(details(st)))
        elif do == "catalog":
            ha.catalog()
        elif do == "setup_complete":
            ha.setup_complete()
        elif do == "history":
            hists.append(h.History(st["name"]))
        elif do == "invoke":
            ops.append(hists[st["h"]].invoke(val(st["proc"]), st["f"], *args(st)))
        elif do == "ok":
            ops[st["o"]].ok(*args(st))
        elif do == "ok_same":
            ops[st["o"]].ok()
        elif do == "fail":
            ops[st["o"]].fail()
        elif do == "info":
            ops[st["o"]].info()
        elif do == "record":
            hists[st["h"]].record(val(st["proc"]), st["type"], st["f"], *args(st))
        else:
            raise AssertionError("unknown step %r: update this test" % do)
    with open(os.environ["HYDO_CASE_RETURNS"], "w", encoding="ascii") as f:
        f.write("".join(ret))


if __name__ == "__main__":
    if sys.argv[1:] == ["--child"]:
        child()
    else:
        unittest.main()
